import json

lines = open('ios_crash.ips').readlines()
raw = ''.join(lines[1:])
raw = raw.replace('\"vmregioninfo\"', '\"vmregioninfo_lower\"')
crash = json.loads(raw)

# Check for any additional crash info - look for recognizable exception patterns
# Check all string fields 
def find_strings(obj, path=''):
    if isinstance(obj, str) and len(obj) > 20:
        if any(kw in obj.lower() for kw in ['exception', 'error', 'null', 'xaml', 'crash', 'maui', 'microsoft']):
            print(f'{path}: {obj[:300]}')
    elif isinstance(obj, dict):
        for k, v in obj.items():
            find_strings(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_strings(v, f'{path}[{i}]')

find_strings(crash)
